/** Public entry point — the only module consumers/docs should import from. */

export {
  useDataGridServerRows,
  type UseDataGridServerRowsOptions,
  type UseDataGridServerRowsResult,
  type ServerRowsPageRequest,
  type ServerRowsRequest,
  type ServerRowsAnswer,
  type DataSourceState,
  type UseDataGridServerRowsScrollOptions,
  type UseDataGridServerRowsScrollResult,
} from "./use-data-grid-server-rows";
export type { SaveRefreshPolicy, SaveRefreshReport } from "./save-refresh";
export { parseServerSpec, ServerSpecError, type ParseServerSpecOptions, type ServerSpecColumnRules, type ServerSpecLimits } from "./parse-server-spec";

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";

/** `end - start`, clamped to 0 for an inverted/empty range. */
export function rangeSize(range: RowRange): number {
  return Math.max(0, range.end - range.start);
}

/** Whether two half-open ranges overlap or touch at an edge (touching ranges are mergeable). */
function rangesAdjacentOrOverlapping(a: RowRange, b: RowRange): boolean {
  return a.start <= b.end && b.start <= a.end;
}

/**
 * Expands `range` by `overscan` rows on each side, then rounds outward so both edges land on a
 * `blockSize` boundary — small scrolls request the same batch repeatedly instead of a slightly
 * different range every tick.
 * Clamps to `[0, total]`.
 */
export function expandRange(range: RowRange, opts: { overscan: number; blockSize: number; total?: number }): RowRange {
  const { overscan, blockSize, total = Infinity } = opts;
  const withOverscan = { start: range.start - overscan, end: range.end + overscan };
  const batch = Math.max(1, blockSize);
  const start = Math.floor(withOverscan.start / batch) * batch;
  const end = Math.ceil(withOverscan.end / batch) * batch;
  return {
    start: Math.max(0, start),
    end: Math.min(total, Math.max(start, end)),
  };
}

/**
 * Subtracts every range in `covered` (already loaded or in-flight, any order/overlap) from
 * `target`, returning the remaining uncovered pieces coalesced into as few ranges as possible —
 * this is the "never re-request a loading/loaded range; merge adjacent gaps" rule as pure math.
 */
export function subtractRanges(target: RowRange, covered: readonly RowRange[]): RowRange[] {
  if (rangeSize(target) === 0) return [];
  const relevant = covered
    .filter((r) => rangeSize(r) > 0 && rangesAdjacentOrOverlapping(r, target))
    .map((r) => ({ start: Math.max(r.start, target.start), end: Math.min(r.end, target.end) }))
    .sort((a, b) => a.start - b.start);

  const merged: RowRange[] = [];
  for (const r of relevant) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }

  const gaps: RowRange[] = [];
  let cursor = target.start;
  for (const r of merged) {
    if (r.start > cursor) gaps.push({ start: cursor, end: r.start });
    cursor = Math.max(cursor, r.end);
  }
  if (cursor < target.end) gaps.push({ start: cursor, end: target.end });
  return gaps;
}

/** Sum of `rangeSize` across a list of ranges — callers pass an already-merged (disjoint) list so this is a true row count, not a double-count of overlaps. */
export function sumRangeSizes(ranges: readonly RowRange[]): number {
  return ranges.reduce((total, r) => total + rangeSize(r), 0);
}

/**
 * Splits `range` into consecutive chunks of at most `max` rows, covering it exactly once; a
 * single chunk when the range already fits. Each chunk obeys the `fetchRows` contract on its
 * own: exactly `chunk.end - chunk.start` rows, positionally aligned to `chunk.start`. A
 * fractional `max` is rounded down so every chunk boundary stays an integral row index.
 */
export function chunkRange(range: RowRange, max: number): RowRange[] {
  const size = rangeSize(range);
  const cap = Math.max(1, Math.floor(max));
  if (size <= cap) return [range];
  const chunks: RowRange[] = [];
  for (let start = range.start; start < range.end; start += cap) {
    chunks.push({ start, end: Math.min(range.end, start + cap) });
  }
  return chunks;
}

/** Splits `range` at the multiples of `size`, so each chunk lies inside one block of the grid of blocks. */
export function chunkAligned(range: RowRange, size: number): RowRange[] {
  const step = Math.max(1, Math.floor(size));
  const chunks: RowRange[] = [];
  for (let start = range.start; start < range.end; ) {
    const end = Math.min(range.end, (Math.floor(start / step) + 1) * step);
    chunks.push({ start, end });
    start = end;
  }
  return chunks;
}

/** Merges a list of ranges (any order/overlap) into the minimal set of disjoint, non-touching ranges. */
export function mergeRanges(ranges: readonly RowRange[]): RowRange[] {
  const sorted = ranges
    .filter((r) => rangeSize(r) > 0)
    .slice()
    .sort((a, b) => a.start - b.start);
  const merged: RowRange[] = [];
  for (const r of sorted) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }
  return merged;
}

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";
import { rangeSize, sumRangeSizes } from "./range-math";

export const DEFAULT_LOAD_DELAY = 100;
const MAX_LOAD_DELAY = 2000;
export const DEFAULT_MAX_CONCURRENT_FETCHES = 3;
const MAX_CONCURRENT_FETCHES = 16;
export const DEFAULT_MAX_LOADED_ROWS = 10_000;

/** A sequential revalidation walks from block 0 to the rendered rows; a tick that would take more blocks is skipped. */
export const MAX_SEQUENTIAL_REVALIDATE_BLOCKS = 10;
export const MIN_REVALIDATE_INTERVAL = 1000;
export const MAX_REVALIDATE_INTERVAL = 2_147_483_647;

export type FetchLimitOptions = { loadDelayMs?: number; maxConcurrentFetches?: number; maxLoadedRows?: number };

export type FetchLimits = {
  loadDelayMs: number;
  maxConcurrentFetches: number;
  /** `Infinity` turns eviction off. */
  maxLoadedRows: number;
  /** The consumer passed a value that is not a number, `NaN`, or negative. */
  maxLoadedRowsInvalid: boolean;
};

function clampedInteger(value: unknown, fallback: number, min: number, max: number): number {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, Math.floor(value))) : fallback;
}

/** Reads the fetch limit options and never throws: a non-number or a negative `maxLoadedRows` falls back to its default, and an out-of-range number clamps. */
export function readFetchLimits(blockSize: number, options: FetchLimitOptions = {}): FetchLimits {
  const rows: unknown = options.maxLoadedRows;
  let maxLoadedRows = DEFAULT_MAX_LOADED_ROWS;
  let maxLoadedRowsInvalid = false;
  if (rows === Infinity) maxLoadedRows = Infinity;
  else if (typeof rows === "number" && Number.isFinite(rows) && rows >= 0) maxLoadedRows = Math.max(blockSize, Math.floor(rows));
  else if (rows !== undefined) maxLoadedRowsInvalid = true;
  return {
    loadDelayMs: clampedInteger(options.loadDelayMs, DEFAULT_LOAD_DELAY, 0, MAX_LOAD_DELAY),
    maxConcurrentFetches: clampedInteger(options.maxConcurrentFetches, DEFAULT_MAX_CONCURRENT_FETCHES, 1, MAX_CONCURRENT_FETCHES),
    maxLoadedRows,
    maxLoadedRowsInvalid,
  };
}

/** The interval in ms, or `null` when revalidation is off; `invalid` marks a value that was set but unusable, `raised` a value below the minimum. */
export function readRevalidateInterval(value: unknown): { interval: number | null; invalid: boolean; raised: boolean } {
  if (value === undefined) return { interval: null, invalid: false, raised: false };
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) return { interval: null, invalid: true, raised: false };
  const interval = Math.min(MAX_REVALIDATE_INTERVAL, Math.floor(value));
  return { interval: Math.max(MIN_REVALIDATE_INTERVAL, interval), invalid: false, raised: interval < MIN_REVALIDATE_INTERVAL };
}

export const MIN_RESHAPE_DELAY = 250;

/** The delay in ms, or `null` when the reshape delay is off; `invalid` marks a value that was set but unusable, `raised` a value below the minimum. */
export function readReshapeDelay(value: unknown): { delay: number | null; invalid: boolean; raised: boolean } {
  if (value === undefined) return { delay: null, invalid: false, raised: false };
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) return { delay: null, invalid: true, raised: false };
  const delay = Math.min(MAX_REVALIDATE_INTERVAL, Math.floor(value));
  return { delay: Math.max(MIN_RESHAPE_DELAY, delay), invalid: false, raised: delay < MIN_RESHAPE_DELAY };
}

/** The wanted range grown by one block on each side, clamped to the result. Abort and eviction act outside it only. */
export function keepRange(wanted: RowRange, blockSize: number, total: number): RowRange {
  return { start: Math.max(0, wanted.start - blockSize), end: Math.min(total, wanted.end + blockSize) };
}

export function rangesIntersect(a: RowRange, b: RowRange): boolean {
  return a.start < b.end && b.start < a.end;
}

/** Uncovered blocks of the wanted range, by block start: the end of the block and when it first entered the range. */
export type Wanted = Map<number, { end: number; since: number }>;

/** Drops the entries that left the wanted range and adds the new ones with `now`; an entry that stays keeps its time. */
export function trackWanted(wanted: Wanted, uncovered: readonly RowRange[], now: number): void {
  const current = new Set<number>();
  for (const block of uncovered) {
    current.add(block.start);
    const known = wanted.get(block.start);
    if (known) known.end = block.end;
    else wanted.set(block.start, { end: block.end, since: now });
  }
  for (const start of wanted.keys()) if (!current.has(start)) wanted.delete(start);
}

/** The blocks that stayed in the wanted range for `delay` ms, nearest to `centre` first and at most `limit`, and when the next one is due. */
export function dueWanted(wanted: Wanted, { now, delay, centre, limit }: { now: number; delay: number; centre: number; limit: number }): { due: RowRange[]; nextAt: number | null } {
  const due: RowRange[] = [];
  let nextAt: number | null = null;
  for (const [start, { end, since }] of wanted) {
    const at = since + delay;
    if (at <= now) due.push({ start, end });
    else if (nextAt === null || at < nextAt) nextAt = at;
  }
  due.sort((a, b) => distanceToCentre(a, centre) - distanceToCentre(b, centre) || a.start - b.start);
  return { due: due.slice(0, Math.max(0, limit)), nextAt };
}

export function distanceToCentre(range: RowRange, centre: number): number {
  return Math.abs((range.start + range.end) / 2 - centre);
}

export type EvictionPick = {
  /** A whole block of the result. */
  block: RowRange;
  /** Slots of the block whose rows stay in `data` because they are protected. They move from loaded to stale. */
  kept: readonly number[];
};

type EvictionInput = {
  /** Merged and ascending. */
  loaded: readonly RowRange[];
  /** Block index -> stamp of the latest report that had the block in its keep range; a block without a stamp is the oldest. */
  viewed: ReadonlyMap<number, number>;
  keep: RowRange;
  blockSize: number;
  cap: number;
  /** The slots of the block whose loaded rows must stay. */
  protectedSlots?: (block: RowRange) => readonly number[];
};

/**
 * Picks whole blocks outside the keep range, least recently viewed first, until the loaded rows fit under `cap`.
 * A block with protected slots frees only its other rows; a block that frees nothing is skipped. The cap is soft.
 */
export function pickEvictions({ loaded, viewed, keep, blockSize, cap, protectedSlots }: EvictionInput): EvictionPick[] {
  let total = sumRangeSizes(loaded);
  if (total <= cap) return [];
  const sizes = new Map<number, number>();
  for (const range of loaded) {
    for (let index = Math.floor(range.start / blockSize); index * blockSize < range.end; index++) {
      const block = { start: index * blockSize, end: (index + 1) * blockSize };
      const overlap = Math.min(range.end, block.end) - Math.max(range.start, block.start);
      sizes.set(index, (sizes.get(index) ?? 0) + overlap);
    }
  }
  const candidates = [...sizes.keys()].filter((index) => !rangesIntersect({ start: index * blockSize, end: (index + 1) * blockSize }, keep));
  candidates.sort((a, b) => (viewed.get(a) ?? 0) - (viewed.get(b) ?? 0) || a - b);
  const picks: EvictionPick[] = [];
  for (const index of candidates) {
    if (total <= cap) break;
    const block = { start: index * blockSize, end: (index + 1) * blockSize };
    const kept = protectedSlots?.(block) ?? [];
    const freed = sizes.get(index)! - kept.length;
    if (freed <= 0) continue;
    picks.push({ block, kept });
    total -= freed;
  }
  return picks;
}

/** The block ranges of a pick, minus the kept slots, as ranges to unload. */
export function unloadRangesOf(pick: EvictionPick): RowRange[] {
  const ranges: RowRange[] = [];
  let from = pick.block.start;
  for (const slot of [...pick.kept].sort((a, b) => a - b)) {
    if (slot > from) ranges.push({ start: from, end: slot });
    from = slot + 1;
  }
  if (from < pick.block.end) ranges.push({ start: from, end: pick.block.end });
  return ranges.filter((range) => rangeSize(range) > 0);
}

/** Drops the stamps of blocks that hold no loaded row and sit outside the keep range. */
export function pruneViewed(viewed: Map<number, number>, loaded: readonly RowRange[], keep: RowRange, blockSize: number): void {
  const held = new Set<number>();
  for (const range of loaded) for (let index = Math.floor(range.start / blockSize); index * blockSize < range.end; index++) held.add(index);
  for (const index of viewed.keys()) {
    if (!held.has(index) && !rangesIntersect({ start: index * blockSize, end: (index + 1) * blockSize }, keep)) viewed.delete(index);
  }
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { serverSpecKey, type DataChange, type DataGridPlugin, type FilterNode, type RowRange, type ServerSpec, type SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { applyChangeWith, holeRowId, isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { readAnswer, type ReadAnswer, type ServerRowsAnswer, type ServerRowsRequest, type WithRowId } from "./read-answer";
import { GUARD_MISSING_MESSAGE, pruneIds, stashGuardedRows, trackDeletes, unionIds, useRefreshGuard, writeBlocks, type GuardedBlock, type ProtectedRows } from "./refresh-guard";
import { cursorKey, MAX_SEEN_CURSORS, needsNextBlock, skeletonCount, startsSequence, stepSequence } from "./scroll-sequence";
import { chunkAligned, chunkRange, expandRange, mergeRanges, rangeSize, subtractRanges, sumRangeSizes } from "./range-math";
import { DEFAULT_MAX_LOADED_ROWS, MAX_SEQUENTIAL_REVALIDATE_BLOCKS, distanceToCentre, dueWanted, keepRange, pickEvictions, pruneViewed, rangesIntersect, readFetchLimits, trackWanted, unloadRangesOf, type FetchLimits, type Wanted } from "./fetch-hygiene";
import { useSaveRefresh, type SaveRefreshOptions, type SaveRefreshPolicy } from "./save-refresh";
import { isolate, scheduleFrame, useMountedPlugins, useReshape, useRevalidation, useServerSpec } from "./server-state";
import type { UseDataGridServerRowsRootProps } from "./use-data-grid-server-rows";

const DEFAULT_OVERSCAN = 30;
const DEFAULT_BLOCK_SIZE = 50;

/** Options of `useDataGridServerRows` in scroll mode. */
export type UseDataGridServerRowsScrollOptions<TData, TCursor = never> = {
  /** `"scroll"` fetches fixed-size blocks as the rendered rows move. Fixed for the life of the hook. */
  mode: "scroll";
  /** Identifies a row. Default: the row's `id` field (a string or number), the same default as `DataGridProvider`. */
  getRowId?: (row: TData, index: number) => string;
  /**
   * How the source is fetched. `"random"` fetches any block by position and needs a `totalRowCount` in every answer (a development
   * warning names an answer without one). `"sequential"` fetches the blocks in order, with a cursor or with offsets and `hasMore`. Default: the first answer picks it, by the rule of `fetchRows`.
   */
  source?: "random" | "sequential";
  /**
   * Resolves rows `[start, end)` of the result. The first answer picks the fetch order:
   * - `totalRowCount` and no `nextCursor`: random access. The grid sizes its rows from the count, and a changed count starts the blocks over.
   * - `nextCursor` (with or without a count), or neither: sequential. The grid shows the loaded rows plus one block of skeletons, and
   *   the next block starts when the rendered rows come near the end. `nextCursor` comes back as `cursor`; `nextCursor: null`,
   *   `hasMore: false`, or an empty block ends the source. Without a cursor, `hasMore` defaults to a full block.
   */
  fetchRows: (request: ServerRowsRequest<TCursor>) => Promise<ServerRowsAnswer<TData, TCursor>>;
  /** The sort, filter, and search while `spec` is not controlled. */
  defaultSpec?: Partial<ServerSpec>;
  /** Controls the sort, filter, and search; pair it with `onSpecChange`. A content change starts the blocks over. */
  spec?: ServerSpec;
  onSpecChange?: (spec: ServerSpec) => void;
  /** Rows per request. Requests align to multiples of it, so small scrolls reuse the same block. Default 50. */
  blockSize?: number;
  /** Rows fetched beyond the rendered rows on each side. Default 30. */
  overscan?: number;
  /**
   * Milliseconds a block stays in the wanted range before its request starts. A fast scroll starts no request until it rests.
   * Block 0, `refresh()`, `retry()`, and the refetch after the first answer or a count change skip it. Default 100, at most 2,000; `0` starts at once.
   */
  loadDelayMs?: number;
  /** Most block requests in flight at once on a random access source. Default 3, at most 16. */
  maxConcurrentFetches?: number;
  /**
   * Most rows kept loaded on a random access source. When more are loaded, the least recently viewed blocks outside the rendered rows
   * plus overscan plus one block unload. Rows with an open edit, a pending save, or an unsaved change, and the row under the active cell, stay in `data`
   * but stop counting as loaded, so the next window fetches their block whole.
   * `Infinity` keeps every row. Default 10,000; a value below `blockSize` counts as `blockSize`.
   */
  maxLoadedRows?: number;
  /**
   * Milliseconds between `refresh()` calls the hook runs itself while the page is visible. A tick waits for a request in flight,
   * and every refresh restarts the clock. A sequential source skips a tick while the rendered rows plus `overscan` end beyond 10 blocks.
   * At least 1000. Off by default.
   */
  revalidateIntervalMs?: number;
  /**
   * Milliseconds to wait after a push marked a row stale before the hook runs a `refresh()` (a reshape) so the server places the
   * rows again. The first push starts the wait and later pushes join it, so a steady feed reshapes at most once per delay. A
   * reshape that falls due during a request, or while the page is hidden, waits and runs once; a sequential source skips it while the
   * rendered rows plus `overscan` end beyond 10 blocks. At least 250. Off by default: a stale row then waits for `reshape()`, `refresh()`, or a spec change.
   */
  reshapeDelayMs?: number;
  /** Fires after a request fails. */
  onError?: (error: unknown) => void;
  /** Fires after the rows of a block land, with the range they cover. The grid shows them on the next frame. */
  onLoaded?: (range: RowRange) => void;
  /** Fires after the hook merged an edit, insert, delete, or revert. Put your handler here; a spread override drops the merge. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Saves a change; spread to the provider through `gridProps.onSave`, where it behaves as the `DataGridProvider` prop of the same name. The hook refreshes after saves settle by `refreshAfterSave`. */
  onSave?: SaveRefreshOptions<TData>["onSave"];
  /** When the hook calls `refresh()` after `onSave` settles: `"settled"` once after every save in flight (default), `"each"` after saves settle without waiting for the saves in flight, `false` never, or a function that gets the counts and returns whether to refresh. A sequential source skips the refresh while the rendered rows plus `overscan` end beyond 10 blocks. */
  refreshAfterSave?: SaveRefreshPolicy;
  /** Plugins the hook mounts after its refresh guard, through `gridProps.plugins`. */
  plugins?: readonly DataGridPlugin<unknown>[];
  /** Fires after the hook's own handler of `gridProps.onRenderedRowsChange`, with the rendered rows. */
  onRenderedRowsChange?: (range: RowRange) => void;
};

/** Props of {@link UseDataGridServerRowsScrollResult.gridProps} that belong to `DataGridProvider`. */
export type UseDataGridServerRowsScrollProviderProps<TData> = {
  /** Sparse at runtime: an unloaded row is a hole, typed as `TData` to match `DataGridProps`. */
  data: readonly TData[];
  /** Gives an unloaded row a placeholder id and a loaded row its own. */
  getRowId: (row: TData, index: number) => string;
  /** Keeps the rows in step with edits, inserts, deletes, and reverts of a refused save. Send changes to your API from `onSave`. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Present when the hook got an `onSave`. */
  onSave?: SaveRefreshOptions<TData>["onSave"];
  /** Reports the rendered rows so the hook can fetch the blocks they need. */
  onRenderedRowsChange: (range: RowRange) => void;
  sortMode: "server";
  filterMode: "server";
  sortState: SortSpec[];
  onSortChange: (next: SortSpec[]) => void;
  filterState: FilterNode[];
  onFilterChange: (next: FilterNode[]) => void;
  searchText: string;
  onSearchTextChange: (next: string) => void;
  /** The row count of the result; `null` until the first block lands, and for a sequential source until it ends or the server sends one. */
  totalRowCount: number | null;
  /** Keeps checks by row id across window moves, evictions, and server sorts and filters. */
  checkedRowsLifetime: "across-filters";
  /** The refresh guard that keeps a refresh from overwriting a row with a pending save or an open edit, then the `plugins` option. */
  plugins: readonly DataGridPlugin<unknown>[];
  /** Sorts on a header click. Override it after the spread. */
  headerClickBehavior: "sort";
};

/** Return value of `useDataGridServerRows` in scroll mode. */
export type UseDataGridServerRowsScrollResult<TData> = {
  /** Spread onto `<DataGrid {...server.gridProps} columns={columns} />`. */
  gridProps: UseDataGridServerRowsScrollProviderProps<TData> & UseDataGridServerRowsRootProps;
  /** The part of `gridProps` for `<DataGridProvider>` in a composed layout. */
  providerProps: UseDataGridServerRowsScrollProviderProps<TData>;
  /** The part of `gridProps` for `<DataGridRoot>` in a composed layout: the loading flag and the error state. */
  rootProps: UseDataGridServerRowsRootProps;
  /** The sort, filter, and search text of the current requests. */
  spec: ServerSpec;
  /** The row count of the result; `null` until the first block lands, and for a sequential source until it ends or the server sends one. */
  totalRowCount: number | null;
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec that no landed block has replaced, or `null`. */
  error: unknown;
  /** Repeats the blocks that failed. Does nothing without an error. */
  retry: () => void;
  /**
   * Fetches the rendered rows again and keeps them on screen until the answers land. Drops every other loaded row. A sequential
   * source refetches from the first block up to the rendered rows. A row with a pending edit, delete, or in-flight save keeps its local state.
   * The hook calls it after saves settle by `refreshAfterSave`; call it yourself with `refreshAfterSave: false` or a void `onSave`.
   */
  refresh: () => void;
  /** Asks the server to place the pushed rows again: one `refresh()` on the next frame, or after `reshapeDelayMs` when it is set. Calls in one frame join. A sequential source skips it while the rendered rows plus `overscan` end beyond 10 blocks. */
  reshape: () => void;
  /** Rows with no data yet; they render as skeletons. A sequential source reports its one block of skeletons. */
  unloadedCount: number;
  /** The loaded ranges, merged and ascending. Not reactive: read it in an effect or a handler. */
  getLoadedRanges: () => readonly RowRange[];
  /**
   * Unloads the rows in `range` and aborts the requests it covers; the next rendered window that covers them fetches them again.
   * Rows with an open edit, a pending save, or an unsaved change, and the row under the active cell, stay in `data` but stop counting as loaded. Does nothing on a sequential source.
   */
  evict: (range: RowRange) => void;
};

type Pending<TData> = GuardedBlock<TData> & { rows: (TData | undefined)[]; mark: number; final?: boolean };
/** `guard` is the set of rows protected when the request started; a retry reuses it. */
type Guard = { ids: ProtectedRows; /** The save count when the request started; later saves are protected too. */ mark: number };
type InFlight = { range: RowRange; controller: AbortController; guard: Guard; /** The answer is being written; the request only waits to settle. */ landed: boolean };
type Failed = { range: RowRange; cursor: unknown; error: unknown };

type Sequence = {
  /** The cursor the next block sends. */
  cursor: unknown;
  ended: boolean;
  /** Rows loaded, without the skeleton rows below them. */
  length: number;
  /** Where the next request starts: the rows the server answered, which exceed `length` by the protected rows dropped from appended blocks. */
  offset: number;
  /** The count the server sent, if any. */
  sentCount: number | null;
  /** A refresh rewrites the rows in place from the first block until the chain passes `keepUntil`. */
  refresh: { keepUntil: number; local: number } | null;
  /** Keys of the cursors the chain returned so far. */
  seen: Set<string>;
};

const freshSequence = (): Sequence => ({ cursor: undefined, ended: false, length: 0, offset: 0, sentCount: null, refresh: null, seen: new Set() });

type Core<TData> = {
  count: number | null;
  /** The first block of the current spec landed. */
  ready: boolean;
  loaded: RowRange[];
  /** Decided by the first answer of the current spec. */
  kind: "unknown" | "random" | "sequence";
