  structural: Set<string>;
  /** Called when the last pending insert or delete save settled. */
  onStructuralSettled: (() => void) | null;
  /** Called when a row's save starts. */
  onSaveStarted: (() => void) | null;
  /** Second save-start listener, for the check that the hook's `onSave` ran. */
  onSaveStartedCheck: (() => void) | null;
  /** Changes the hook's `onDataChange` merged, and changes the plugin observed; a gap means a provider `onDataChange` replaced the merge. */
  merged: number;
  seen: number;
  mergeWarned: boolean;
  /** Called when the last saving row leaves `"saving"`. */
  onSavesSettled: (() => void) | null;
  /** Called when the grid asks for a reshape: `reconcileView()`, an immediate push, or a deferred push that marked a row. */
  onReshape: ((trigger: "urgent" | "stale") => void) | null;
  /** Cells that a push wrote while a request was open: row id -> column id -> value and the generation of the push. Dropped when no request is open. */
  pushed: Map<string, Map<string, { value: unknown; at: number }>>;
  trackUnacknowledged: boolean;
  /** Rows with a local edit or insert that no save and no landed block has acknowledged; eviction keeps them. */
  unacknowledged: Set<string>;
};

function setListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onStructuralSettled = listener;
}

function setSaveListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onSaveStarted = listener;
}

function setSaveCheckOn(holder: Holder, listener: (() => void) | null) {
  holder.onSaveStartedCheck = listener;
}

function setSettledListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onSavesSettled = listener;
}

function setReshapeOn(holder: Holder, listener: ((trigger: "urgent" | "stale") => void) | null) {
  holder.onReshape = listener;
}

function hasSaving(status: ReadonlyMap<string, string>): boolean {
  for (const value of status.values()) if (value === "saving") return true;
  return false;
}

function trackStructural(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string }[] }) {
  if (change.source === "stream" || change.source === "rollback") return;
  const status = holder.store?.getState().saveStatus;
  for (const op of change.ops) if ((op.type === "insert" || op.type === "delete") && status?.get(op.rowId) === "saving") holder.structural.add(op.rowId);
}

function trackUnacknowledgedRows(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string }[] }) {
  if (!holder.trackUnacknowledged || change.source === "stream" || change.source === "rollback") return;
  for (const op of change.ops) {
    if (op.type === "update" || op.type === "insert") holder.unacknowledged.add(op.rowId);
    else if (op.type === "delete") holder.unacknowledged.delete(op.rowId);
  }
}

function trackPushedCells(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string; cells?: readonly { columnId: string; value: unknown }[] }[] }) {
  if (!holder.recording || change.source !== "stream") return;
  for (const op of change.ops) {
    if (op.type !== "update" || !op.cells) continue;
    const at = ++holder.generation;
    let cells = holder.pushed.get(op.rowId);
    if (!cells) holder.pushed.set(op.rowId, (cells = new Map<string, { value: unknown; at: number }>()));
    for (const cell of op.cells) cells.set(cell.columnId, { value: cell.value, at });
  }
}

function pushedSinceOn(holder: Holder, generation: number): ReadonlyMap<string, ReadonlyMap<string, unknown>> | null {
  let rows: Map<string, Map<string, unknown>> | null = null;
  for (const [rowId, cells] of holder.pushed) {
    let fresh: Map<string, unknown> | null = null;
    for (const [columnId, cell] of cells) if (cell.at > generation) (fresh ??= new Map()).set(columnId, cell.value);
    if (fresh) (rows ??= new Map()).set(rowId, fresh);
  }
  return rows;
}

function markEditedOn(holder: Holder) {
  holder.edited = true;
  holder.merged += 1;
}

function trackSaves(holder: Holder, state: DataGridReadState, prev: DataGridReadState) {
  if (state.saveStatus === prev.saveStatus) return;
  if (holder.unacknowledged.size > 0) {
    for (const [id, status] of prev.saveStatus) if (status === "saving" && state.saveStatus.get(id) !== "saving") holder.unacknowledged.delete(id);
  }
  if (holder.structural.size > 0) {
    for (const [id, status] of prev.saveStatus) {
      if (status === "saving" && state.saveStatus.get(id) !== "saving" && holder.structural.delete(id) && holder.structural.size === 0) holder.onStructuralSettled?.();
    }
  }
  let started = false;
  for (const [id, status] of state.saveStatus) {
    if (status !== "saving" || prev.saveStatus.get(id) === "saving") continue;
    started = true;
    if (holder.recording) holder.savedAt.set(id, ++holder.generation);
  }
  if (started) {
    holder.onSaveStarted?.();
    holder.onSaveStartedCheck?.();
  }
  if (holder.onSavesSettled && hasSaving(prev.saveStatus) && !hasSaving(state.saveStatus)) holder.onSavesSettled();
}

function savedSinceOn(holder: Holder, generation: number): ProtectedRows {
  let ids: Set<string> | null = null;
  for (const [id, at] of holder.savedAt) if (at > generation) (ids ??= new Set()).add(id);
  return ids;
}

function markSavesOn(holder: Holder): number {
  holder.recording = true;
  return holder.generation;
}

function pruneSavesOn(holder: Holder, oldestGeneration: number | null) {
  holder.recording = oldestGeneration !== null;
  if (oldestGeneration === null) {
    holder.savedAt.clear();
    holder.pushed.clear();
    return;
  }
  for (const [id, at] of holder.savedAt) if (at <= oldestGeneration) holder.savedAt.delete(id);
  for (const [id, cells] of holder.pushed) {
    for (const [columnId, cell] of cells) if (cell.at <= oldestGeneration) cells.delete(columnId);
    if (cells.size === 0) holder.pushed.delete(id);
  }
}

function createGuardPlugin(holder: Holder): DataGridPlugin<unknown> {
  function RefreshGuardMount() {
    const store = useDataGridStoreApi();
    useEffect(() => {
      holder.store = store;
      holder.everMounted = true;
      const unsubscribe = store.subscribe((state, prev) => trackSaves(holder, state, prev));
      setServerReshapeHandler(store, (trigger) => holder.onReshape?.(trigger));
      return () => {
        setServerReshapeHandler(store, null);
        unsubscribe();
        holder.store = null;
      };
    }, [store]);
    return null;
  }
  return {
    name: "server-rows-refresh-guard",
    Mount: RefreshGuardMount,
    onDataChange: (_next, change) => {
      holder.seen += 1;
      if (isDev() && holder.merged < holder.seen && !holder.mergeWarned) {
        holder.mergeWarned = true;
        console.warn("[data-grid-server] a change reached the grid, but the hook's onDataChange merge did not run: an onDataChange prop on DataGridProvider after {...gridProps} replaced it, so edits vanish on the next render. Pass your handler to the hook's onDataChange option instead");
      }
      trackStructural(holder, change);
      trackUnacknowledgedRows(holder, change);
      trackPushedCells(holder, change);
    },
  };
}

export type RefreshGuardOptions = {
  /** Remember rows with a local change that no save acknowledged, for `evictionProtected`. Scroll mode only. */
  trackUnacknowledged?: boolean;
};

/** A plugin that gives the hook, which sits outside the provider, read access to the grid's save status and edit session. */
export function useRefreshGuard({ trackUnacknowledged = false }: RefreshGuardOptions = {}) {
  const [holder] = useState<Holder>(() => ({ store: null, everMounted: false, edited: false, generation: 0, recording: false, savedAt: new Map(), structural: new Set(), onStructuralSettled: null, onSaveStarted: null, onSaveStartedCheck: null, merged: 0, seen: 0, mergeWarned: false, onSavesSettled: null, onReshape: null, pushed: new Map(), trackUnacknowledged, unacknowledged: new Set() }));
  const [plugins] = useState(() => [createGuardPlugin(holder)]);
  const savingRows = useCallback((): ProtectedRows => {
    const state = holder.store?.getState();
    if (!state) return null;
    const ids = new Set<string>();
    for (const [rowId, status] of state.saveStatus) if (status === "saving") ids.add(rowId);
    return ids.size > 0 ? ids : null;
  }, [holder]);
  const protectedRows = useCallback((): ProtectedRows => {
    const editing = holder.store?.getState().editing;
    return editing ? unionIds(savingRows(), new Set([editing.rowId])) : savingRows();
  }, [holder, savingRows]);
  const guardMissing = useCallback(() => holder.edited && !holder.everMounted, [holder]);
  const markEdited = useCallback(() => markEditedOn(holder), [holder]);
  const saveMark = useCallback(() => markSavesOn(holder), [holder]);
  const savedSince = useCallback((mark: number) => savedSinceOn(holder, mark), [holder]);
  const setSettleListener = useCallback((listener: (() => void) | null) => setListenerOn(holder, listener), [holder]);
  const setSaveStartListener = useCallback((listener: (() => void) | null) => setSaveListenerOn(holder, listener), [holder]);
  const setSaveCheckListener = useCallback((listener: (() => void) | null) => setSaveCheckOn(holder, listener), [holder]);
  const setSavesSettledListener = useCallback((listener: (() => void) | null) => setSettledListenerOn(holder, listener), [holder]);
  const setReshapeListener = useCallback((listener: ((trigger: "urgent" | "stale") => void) | null) => setReshapeOn(holder, listener), [holder]);
  const forgetStructural = useCallback(() => {
    holder.structural.clear();
    holder.unacknowledged.clear();
  }, [holder]);
  const evictionProtected = useCallback((): ProtectedRows => {
    const ids = holder.unacknowledged.size > 0 ? unionIds(protectedRows(), holder.unacknowledged) : protectedRows();
    const state = holder.store?.getState();
    const active = state?.activeCell ? rowIdAtViewRow(state, state.activeCell.row) : undefined;
    return active === undefined ? ids : unionIds(ids, new Set([active]));
  }, [holder, protectedRows]);
  const acknowledge = useCallback((rowId: string) => holder.unacknowledged.delete(rowId), [holder]);
  const unacknowledgedRows = useCallback((): ReadonlySet<string> | null => (holder.unacknowledged.size > 0 ? holder.unacknowledged : null), [holder]);
  const pruneSaves = useCallback((oldestMark: number | null) => pruneSavesOn(holder, oldestMark), [holder]);
  const streamUpdateRow = useCallback(
    <TData,>(change: DataChange<TData>) => {
      const columns = holder.store?.getState().columns;
      return columns ? rowOfStreamUpdate(change, columns) : undefined;
    },
    [holder],
  );
  const overlayPushed = useCallback(
    <TData,>(rows: readonly TData[], mark: number, start: number, idOf: (row: TData, index: number) => string): TData[] => {
      const pushed = pushedSinceOn(holder, mark);
      const columns = holder.store?.getState().columns;
      if (pushed === null || !columns) return rows as TData[];
      const byId = new Map(columns.map((column) => [column.id, column] as const));
      return rows.map((row, index) => {
        const cells = row === undefined ? undefined : pushed.get(idOf(row, start + index));
        if (!cells) return row;
        let next = row;
        for (const [columnId, value] of cells) {
          const column = byId.get(columnId);
          if (column) next = setCellValue(next, column as never, value as never);
        }
        return next;
      });
    },
    [holder],
  );
  return { setSaveCheckListener, plugins, protectedRows, savingRows, guardMissing, markEdited, saveMark, savedSince, pruneSaves, overlayPushed, streamUpdateRow, setSettleListener, setSaveStartListener, setSavesSettledListener, setReshapeListener, forgetStructural, evictionProtected, acknowledge, unacknowledgedRows };
}

/**
 * The row a stream update writes onto the row that `data` holds now. A push made on a row that a block has replaced since carries
 * the whole row it was made on; writing only its cells keeps the old values of the other cells from coming back.
 * `applyChange` calls it with the current row, so it needs no pass of its own over the rows.
 */
export function rowOfStreamUpdate<TData>(change: DataChange<TData>, columns: readonly { id: string }[]) {
  if (change.source !== "stream") return undefined;
  const byId = new Map(columns.map((column) => [column.id, column] as const));
  return (op: Extract<DataChange<TData>["ops"][number], { type: "update" }>, current: TData): TData => {
    if (!op.cells || current === op.prev) return op.row;
    let row = current;
    for (const cell of op.cells) {
      const column = byId.get(cell.columnId);
      if (column) row = setCellValue(row, column as never, cell.value as never);
    }
    return row;
  };
}

export const GUARD_MISSING_MESSAGE =
  "refresh cannot protect rows with a pending save or an open edit because the refresh guard plugin never mounted; pass your own plugins through the `plugins` option of useDataGridServerRows instead of a `plugins` prop after the gridProps spread";

/** Applies the rule to an incoming page: a deleted row is dropped, a protected row keeps its local value by id, and a protected row the page lacks stays at the end. */
export function keepProtectedRows<TData>(
  incoming: readonly TData[],
  current: readonly TData[],
  guarded: ProtectedRows,
  deleted: ReadonlySet<string>,
  keepMissing: boolean,
  idOf: (row: TData, index: number) => string,
): TData[] {
  if (guarded === null && deleted.size === 0) return incoming as TData[];
  const local = new Map<string, TData>();
  current.forEach((row, index) => {
    const id = idOf(row, index);
    if (guarded?.has(id)) local.set(id, row);
  });
  const placed = new Set<string>();
  const page: TData[] = [];
  incoming.forEach((row, index) => {
    const id = idOf(row, index);
    if (deleted.has(id)) return;
    placed.add(id);
    page.push(local.get(id) ?? row);
  });
  if (keepMissing) for (const [id, row] of local) if (!placed.has(id) && !deleted.has(id)) page.push(row);
  return page;
}

/** Notes the rows a change deleted, and forgets a row that a change inserted again. */
export function trackDeletes(deleted: Set<string>, change: { ops: readonly { type: string; rowId: string }[] }) {
  for (const op of (change.ops as typeof change.ops | undefined) ?? []) {
    if (op.type === "delete") deleted.add(op.rowId);
    else if (op.type === "insert") deleted.delete(op.rowId);
  }
}

/** Drops the rows whose delete is no longer pending. */
export function pruneIds(ids: Set<string>, stillSaving: ProtectedRows) {
  for (const id of ids) if (!stillSaving?.has(id)) ids.delete(id);
}

/** The union of two protected sets; either may be `null`. */
export function unionIds(a: ProtectedRows, b: ProtectedRows): ProtectedRows {
  if (a === null) return b;
  if (b === null || a === b) return a;
  return new Set([...a, ...b]);
}

export type GuardedBlock<TData> = { start: number; rows: readonly (TData | undefined)[]; guard: ProtectedRows };

/** Moves the guarded rows in the given index ranges into `into`, for the block that brings their ids back. */
export function stashGuardedRows<TData>(
  rows: readonly (TData | undefined)[],
  ranges: readonly { start: number; end: number }[],
  guarded: ReadonlySet<string>,
  into: Map<string, TData>,
  idOf: (row: TData, index: number) => string,
  orphans: Map<string, { row: TData; slot: number }>,
) {
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && guarded.has(idOf(row, index))) {
        into.set(idOf(row, index), row);
        orphans.set(idOf(row, index), { row, slot: index });
      }
    }
  }
}

function findSlot<TData>(rows: readonly (TData | undefined)[], ranges: readonly { start: number; end: number }[], id: string, idOf: (row: TData, index: number) => string, near: number): number {
  for (const index of [near - 1, near + 1]) {
    const row = rows[index];
    if (row !== undefined && idOf(row, index) === id) return index;
  }
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && idOf(row, index) === id) return index;
    }
  }
  return -1;
}

/**
 * Writes blocks into a copy of `prev`. A block guards the ids it was requested with plus the `live` ones: such a row keeps its
 * local value and appears once, at the index the answer gives it. `displaced` holds a guarded row that an earlier block overwrote,
 * for the block that brings its id back. `cleared` lists the slots left empty because a row moved away from them.
 */
export function writeBlocks<TData>(
  prev: readonly (TData | undefined)[],
  blocks: readonly GuardedBlock<TData>[],
  live: ProtectedRows,
  displaced: Map<string, TData>,
  ranges: readonly { start: number; end: number }[],
  idOf: (row: TData, index: number) => string,
  memory: { orphans: Map<string, { row: TData; slot: number }>; carried: Set<string> },
  final = false,
): { rows: (TData | undefined)[]; cleared: number[]; restored: number[] } {
  const next = prev.slice();
  const emptied: number[] = [];
  const restored: number[] = [];
  const { carried, orphans: overwritten } = memory;
  const stillProtected = new Set<string>();
  for (const { start, rows, guard } of blocks) {
    const guarded = unionIds(guard, live);
    if (guarded !== null) for (const id of guarded) stillProtected.add(id);
    for (let i = 0; i < rows.length && start + i < next.length; i++) {
      const slot = start + i;
      const incoming = rows[i];
      if (guarded === null) {
        next[slot] = incoming;
        continue;
      }
      const occupant = next[slot];
      const occupantId = occupant === undefined ? undefined : idOf(occupant, slot);
      const incomingId = incoming === undefined ? undefined : idOf(incoming, slot);
      if (incomingId !== undefined) carried.add(incomingId);
      if (incomingId !== undefined && guarded.has(incomingId)) {
        if (occupantId === incomingId) continue;
        if (occupantId !== undefined && guarded.has(occupantId)) {
          displaced.set(occupantId, occupant as TData);
          overwritten.set(occupantId, { row: occupant as TData, slot });
        }
        const from = findSlot(next, ranges, incomingId, idOf, slot);
        const local = from >= 0 ? next[from] : displaced.get(incomingId);
        next[slot] = local ?? incoming;
        if (local !== undefined && from >= 0) {
          next[from] = undefined;
          emptied.push(from);
        }
        continue;
      }
      if (occupantId !== undefined && guarded.has(occupantId)) {
        displaced.set(occupantId, occupant as TData);
        overwritten.set(occupantId, { row: occupant as TData, slot });
      }
      next[slot] = incoming;
    }
  }
  // Nothing else is loading: a protected row that the answer does not carry (a pending insert) returns to its own slot when no answer row sits there.
  if (final) {
    for (const [id, { row, slot }] of overwritten) {
      if (carried.has(id) || !stillProtected.has(id) || slot >= next.length || next[slot] !== undefined) continue;
      next[slot] = row;
      restored.push(slot);
    }
  }
  return { rows: next, cleared: emptied.filter((slot) => next[slot] === undefined), restored };
}

import type { FilterGroup, FilterNode, FilterOperator, FilterOperatorInput, FilterSpec, ServerSpec, SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { MAX_FILTER_GROUP_DEPTH, MAX_SPEC_SEARCH_LENGTH, MAX_SPEC_SORTS, filterOperatorInput, isBuiltInOperator } from "@/registry/default/components/data-grid/data-grid-sdk";

/** What a request may do with one column. Every field is optional. */
export type ServerSpecColumnRules = {
  /** `false` rejects a sort on the column. Default `true`. */
  sortable?: boolean;
  /** `false` rejects a filter on the column. Default `true`. */
  filterable?: boolean;
  /** Allowed operators. Default: every built-in operator. A custom operator in `customOperators` is allowed whether or not this list names it. */
  operators?: readonly FilterOperator[];
  /** Custom operators the column accepts, with the value shape of each. */
  customOperators?: Readonly<Record<string, FilterOperatorInput>>;
};

/** Bounds that apply to the whole request. Every field is optional; a negative or non-finite value keeps the default. Groups nest at most 2 levels deep. */
export type ServerSpecLimits = {
  /** Most sort entries. Default 64. */
  maxSorts?: number;
  /** Most filter rows in the tree. Default 64. */
  maxFilters?: number;
  /** Most filter groups in the tree. Default 16. */
  maxGroups?: number;
  /** Longest text of one filter value, one list entry, or one range bound. Default 1000. */
  maxValueLength?: number;
  /** Most entries of an `isAnyOf` or `isNoneOf` list. Default 1000. */
  maxListLength?: number;
  /** Longest `searchText`. Default 500. */
  maxSearchLength?: number;
};

export type ParseServerSpecOptions = {
  /** The columns a request may name: a list of ids (no extra rules), or a map from id to its rules. */
  columns: readonly string[] | Readonly<Record<string, ServerSpecColumnRules>>;
  limits?: ServerSpecLimits;
};

/** Thrown by {@link parseServerSpec}. `path` names the offending part of the request, such as `filters[2].value`. */
export class ServerSpecError extends Error {
  readonly path: string;
  constructor(path: string, message: string) {
    super(`${path}: ${message}`);
    this.name = "ServerSpecError";
    this.path = path;
  }
}

const DEFAULT_LIMITS = { maxSorts: MAX_SPEC_SORTS, maxFilters: 64, maxGroups: 16, maxValueLength: 1000, maxListLength: 1000, maxSearchLength: MAX_SPEC_SEARCH_LENGTH } satisfies Required<ServerSpecLimits>;

type Budget = { filters: number; groups: number };

type Raw = { sorts?: unknown; filters?: unknown; searchText?: unknown; columnId?: unknown; direction?: unknown; join?: unknown; operator?: unknown; value?: unknown };

const isRecord = (value: unknown): value is Raw => typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * Turns an untrusted request body into a bounded, typed {@link ServerSpec}, or throws {@link ServerSpecError}. It checks the
 * shape, the column ids, the operators, the value shapes, and the size of the tree, and drops every key it does not know.
 * It does not build a query: map the result to your query layer.
 *
 * @example
 * const spec = parseServerSpec(body.spec, { columns: ["name", "status", "age"] });
 */
export function parseServerSpec(input: unknown, options: ParseServerSpecOptions): ServerSpec {
  const limits = { ...DEFAULT_LIMITS };
  for (const key of Object.keys(DEFAULT_LIMITS) as (keyof ServerSpecLimits)[]) {
    const wanted = options.limits?.[key];
    if (wanted !== undefined && Number.isFinite(wanted) && wanted >= 0) limits[key] = wanted;
  }
  const rules = columnRules(options.columns);
  if (!isRecord(input)) throw new ServerSpecError("spec", "must be an object");
  return {
    sorts: parseSorts(input.sorts, rules, limits),
    filters: parseFilters(input.filters, rules, limits),
    searchText: parseSearch(input.searchText, limits),
  };
}

function columnRules(columns: ParseServerSpecOptions["columns"]): ReadonlyMap<string, ServerSpecColumnRules> {
  if (Array.isArray(columns)) return new Map((columns as readonly string[]).map((id) => [id, {}]));
  return new Map(Object.entries(columns as Readonly<Record<string, ServerSpecColumnRules>>));
}

function parseSearch(value: unknown, limits: Required<ServerSpecLimits>): string {
  if (value === undefined || value === null) return "";
  if (typeof value !== "string") throw new ServerSpecError("searchText", "must be a string");
  if (value.length > limits.maxSearchLength) throw new ServerSpecError("searchText", `is longer than ${limits.maxSearchLength}`);
  return value;
}

function parseSorts(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): SortSpec[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new ServerSpecError("sorts", "must be an array");
  if (value.length > limits.maxSorts) throw new ServerSpecError("sorts", `holds more than ${limits.maxSorts} entries`);
  return value.map((entry: unknown, index) => {
    const path = `sorts[${index}]`;
    if (!isRecord(entry)) throw new ServerSpecError(path, "must be an object");
    const columnId = knownColumn(entry.columnId, rules, `${path}.columnId`);
    if (rules.get(columnId)!.sortable === false) throw new ServerSpecError(`${path}.columnId`, `"${columnId}" cannot be sorted`);
    if (entry.direction !== "asc" && entry.direction !== "desc") throw new ServerSpecError(`${path}.direction`, 'must be "asc" or "desc"');
    return { columnId, direction: entry.direction };
  });
}

function knownColumn(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, path: string): string {
  if (typeof value !== "string" || !rules.has(value)) throw new ServerSpecError(path, "names an unknown column");
  return value;
}

function parseFilters(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): FilterNode[] {
  if (value === undefined || value === null) return [];
  const budget: Budget = { filters: 0, groups: 0 };
  return parseNodes(value, "filters", 0, rules, limits, budget);
}

function parseNodes(value: unknown, path: string, depth: number, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterNode[] {
  if (!Array.isArray(value)) throw new ServerSpecError(path, "must be an array");
  return value.map((node: unknown, index) => {
    const nodePath = `${path}[${index}]`;
    if (!isRecord(node)) throw new ServerSpecError(nodePath, "must be an object");
    if (Object.hasOwn(node, "filters")) return parseGroup(node, nodePath, depth + 1, rules, limits, budget);
    return parseRow(node, nodePath, rules, limits, budget);
  });
}

function parseGroup(node: Raw, path: string, depth: number, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterGroup {
  if (depth > MAX_FILTER_GROUP_DEPTH) throw new ServerSpecError(path, `nests groups deeper than ${MAX_FILTER_GROUP_DEPTH}`);
  budget.groups += 1;
  if (budget.groups > limits.maxGroups) throw new ServerSpecError(path, `holds more than ${limits.maxGroups} groups`);
  if (node.join !== "and" && node.join !== "or") throw new ServerSpecError(`${path}.join`, 'must be "and" or "or"');
  return { join: node.join, filters: parseNodes(node.filters, `${path}.filters`, depth, rules, limits, budget) };
}

function parseRow(node: Raw, path: string, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterSpec {
  budget.filters += 1;
  if (budget.filters > limits.maxFilters) throw new ServerSpecError(path, `holds more than ${limits.maxFilters} filters`);
  const columnId = knownColumn(node.columnId, rules, `${path}.columnId`);
  const column = rules.get(columnId)!;
  if (column.filterable === false) throw new ServerSpecError(`${path}.columnId`, `"${columnId}" cannot be filtered`);
  if (typeof node.operator !== "string") throw new ServerSpecError(`${path}.operator`, "must be a string");
  const operator = node.operator;
  const custom = column.customOperators && Object.hasOwn(column.customOperators, operator) ? column.customOperators[operator] : undefined;
  const allowed = column.operators ? column.operators.includes(operator) || custom !== undefined : isBuiltInOperator(operator) || custom !== undefined;
  if (!allowed) throw new ServerSpecError(`${path}.operator`, `"${operator.slice(0, 40)}" is not allowed on "${columnId.slice(0, 40)}"`);
  const input = custom ?? filterOperatorInput(operator);
  const value = parseValue(node.value, input, `${path}.value`, limits);
  return value === undefined ? { columnId, operator } : { columnId, operator, value };
}

function text(value: unknown, path: string, limits: Required<ServerSpecLimits>): string {
  if (typeof value !== "string") throw new ServerSpecError(path, "must be a string");
  if (value.length > limits.maxValueLength) throw new ServerSpecError(path, `is longer than ${limits.maxValueLength}`);
  return value;
}

function parseValue(value: unknown, input: FilterOperatorInput, path: string, limits: Required<ServerSpecLimits>): FilterSpec["value"] {
  if (input === "none") return undefined;
  if (input === "single") return text(value, path, limits);
  if (!Array.isArray(value)) throw new ServerSpecError(path, "must be an array");
  if (input === "range") {
    if (value.length !== 2) throw new ServerSpecError(path, "must hold two bounds");
    return [text(value[0], `${path}[0]`, limits), text(value[1], `${path}[1]`, limits)];
  }
  if (value.length > limits.maxListLength) throw new ServerSpecError(path, `holds more than ${limits.maxListLength} entries`);
  return value.map((entry: unknown, index) => text(entry, `${path}[${index}]`, limits));
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { DataChange, SaveAck } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";

/** What `refreshAfterSave` sees when it decides: the saves that settled since the last refresh. */
export type SaveRefreshReport = {
  /** Saves the server accepted (`onSave` returned a promise that resolved with nothing or without `rejected`). */
  saved: number;
  /** Saves that resolved with `{ rejected }`. */
  rejected: number;
  /** Saves whose `onSave` threw or whose promise rejected. */
  failed: number;
  /** The changes of those saves, oldest first, at most 100, for a policy that decides per change. */
  changes: readonly DataChange<unknown>[];
  /** Saves still in flight when the decision runs; above 0 only when the 10 second wait forced it. */
  pending: number;
};

/**
 * When the hook fetches again after `onSave` settles.
 * - `"settled"`: once, after every save in flight has settled (or after 10 seconds, so one stuck save cannot stop the refresh). A burst of saves costs one request. After the 10 seconds, each save still in flight refreshes when it settles, until a new save starts a new wait.
 * - `"each"`: after saves settle, without waiting for the saves still in flight. Saves that settle in the same task share one refresh.
 * - `false`: never. Call `refresh()` yourself.
 * - a function: once after every save in flight has settled (or after the same 10 seconds), when it returns `true`. A throw counts as `false`.
 *
 * Only a promise from `onSave` counts as a save: a handler that returns nothing has not told the grid when the server has the change, so it never triggers a refresh (call `refresh()` yourself). A refresh needs at least one save the server answered; saves that all threw skip it.
 */
export type SaveRefreshPolicy = false | "each" | "settled" | ((report: SaveRefreshReport) => boolean);

export type SaveRefreshOptions<TData> = {
  /** Saves a change. Spread through `gridProps.onSave`; it behaves as the `DataGridProvider` prop of the same name. */
  onSave?: (change: DataChange<TData>) => void | Promise<SaveAck<TData>>;
  /** Default `"settled"` while `onSave` is set. */
  refreshAfterSave?: SaveRefreshPolicy;
};

const isThenable = (value: unknown): value is PromiseLike<unknown> => typeof (value as PromiseLike<unknown> | null)?.then === "function";

/** Longest wait for saves in flight before the `"settled"` policies decide anyway, so one save that never settles cannot stop every later refresh. */
export const SAVE_REFRESH_MAX_WAIT_MS = 10_000;

/**
 * Wraps the caller's `onSave` so the hook refreshes after saves settle by the caller's policy. Returns `undefined` without an
 * `onSave`, so spreading `gridProps` never overrides a provider `onSave` of your own.
 */
export function useSaveRefresh<TData>(options: SaveRefreshOptions<TData> = {}, refresh: () => void, setSaveCheckListener?: (listener: (() => void) | null) => void): ((change: DataChange<TData>) => void | Promise<SaveAck<TData>>) | undefined {
  const live = useRef({ options, refresh });
  useLayoutEffect(() => {
    live.current = { options, refresh };
  });
  const state = useRef({ inflight: 0, counts: { saved: 0, rejected: 0, failed: 0 }, changes: [] as DataChange<unknown>[], scheduled: false, settleTimer: null as ReturnType<typeof setTimeout> | null, mounted: true, waitExpired: false, maxWait: null as ReturnType<typeof setTimeout> | null });
  useEffect(() => {
    state.current.mounted = true;
    return () => {
      const current = state.current;
      current.mounted = false;
      if (current.maxWait !== null) clearTimeout(current.maxWait);
      if (current.settleTimer !== null) clearTimeout(current.settleTimer);
      current.maxWait = null;
      current.settleTimer = null;
      current.scheduled = false;
    };
  }, []);

  const decide = useCallback((force = false) => {
    const current = state.current;
    current.scheduled = false;
    current.settleTimer = null;
    if (current.maxWait !== null && (force || current.inflight === 0)) {
      clearTimeout(current.maxWait);
      current.maxWait = null;
    }
    if (!current.mounted) return;
    const policy = live.current.options.refreshAfterSave ?? "settled";
    if (policy === false) {
      current.counts = { saved: 0, rejected: 0, failed: 0 };
      current.changes = [];
      return;
    }
    if (policy !== "each" && current.inflight > 0 && !force) return;
    if (current.counts.saved + current.counts.rejected === 0) {
      current.counts = { saved: 0, rejected: 0, failed: 0 };
      current.changes = [];
      if (force) current.waitExpired = true;
      return;
    }
    current.waitExpired = (force || current.waitExpired) && current.inflight > 0;
    const report: SaveRefreshReport = { ...current.counts, changes: current.changes, pending: current.inflight };
    current.counts = { saved: 0, rejected: 0, failed: 0 };
    current.changes = [];
    if (typeof policy === "function") {
      let wanted = false;
      try {
        wanted = policy(report);
      } catch (error) {
        console.error("[data-grid-server] refreshAfterSave threw", error);
      }
      if (!wanted) return;
    }
    live.current.refresh();
  }, []);

  const settle = useCallback(
    (kind: "saved" | "rejected" | "failed", change: DataChange<TData>) => {
      const current = state.current;
      current.counts[kind] += 1;
      if (current.changes.length < 100) current.changes.push(change);
      if (current.scheduled) return;
      current.scheduled = true;
      current.settleTimer = setTimeout(() => decide(current.waitExpired), 0); // after the grid has settled the row, so the refresh sees it as saved
    },
    [decide],
  );

  const hasSave = options.onSave !== undefined;
  const calls = useRef({ ran: 0, seen: 0, warned: false });
  useEffect(() => {
    if (!hasSave || !setSaveCheckListener || !isDev()) return;
    setSaveCheckListener(() => {
      const counts = calls.current;
      counts.seen += 1;
      setTimeout(() => {
        if (counts.ran >= counts.seen || counts.warned) return;
        counts.warned = true;
        console.warn("[data-grid-server] a save started, but the onSave you gave the hook did not run: an onSave prop on DataGridProvider after {...gridProps} replaced it, so refreshAfterSave is off. Pass onSave to the hook, or call refresh() yourself");
      }, 0);
    });
    return () => setSaveCheckListener(null);
  }, [hasSave, setSaveCheckListener]);
  const onSave = useCallback(
    (change: DataChange<TData>): void | Promise<SaveAck<TData>> => {
      const run = live.current.options.onSave;
      if (!run) return undefined;
      calls.current.ran += 1;
      let result: void | Promise<SaveAck<TData>>;
      try {
        result = run(change);
      } catch (error) {
        settle("failed", change);
        throw error;
      }
      if (!isThenable(result)) return result;
      state.current.inflight += 1;
      if (state.current.maxWait === null) {
        state.current.waitExpired = false;
        state.current.maxWait = setTimeout(() => decide(true), SAVE_REFRESH_MAX_WAIT_MS);
      }
      return Promise.resolve(result).then(
        (ack) => {
          state.current.inflight -= 1;
          settle(ack && (ack.rejected?.length ?? 0) > 0 ? "rejected" : "saved", change);
          return ack;
        },
        (error: unknown) => {
          state.current.inflight -= 1;
          settle("failed", change);
          throw error;
        },
      );
    },
    [settle, decide],
  );
  return hasSave ? onSave : undefined;
}

import type { RowRange, ServerSpec } from "@/registry/default/components/data-grid/data-grid";

/** Largest row count the server contract accepts; a bigger count clamps to it. */
export const MAX_ROW_COUNT = 10_000_000;

/** What `fetchRows` receives in every mode. */
export type ServerRowsRequest<TCursor = never> = {
  /** The sort, filter, and search of this request. */
  spec: ServerSpec;
  /** Index of the first requested row in the result. */
  start: number;
  /** One past the last requested row; `end - start` is the limit. */
  end: number;
  /** Cursor sources: the `nextCursor` of the block or page before; `undefined` for the first one and for every other source. */
  cursor: TCursor | undefined;
  /** Aborted when a newer request replaces this one, when a scroll-mode block leaves the rendered rows by more than `overscan` plus one block, on a spec change, and on unmount. */
  signal: AbortSignal;
};

/** Pages mode adds the page address; `start` is `(page - 1) * pageSize`. */
export type ServerRowsPageRequest<TCursor = never> = ServerRowsRequest<TCursor> & {
  /** 1-based page. */
  page: number;
  pageSize: number;
};

/** What `fetchRows` resolves with in every mode. */
export type ServerRowsAnswer<TData, TCursor = never> = {
  /** At most `end - start` rows, in order from `start`; extra rows are dropped with a development warning. A repeated row id keeps its first row; the later copy leaves its slot empty in random-access scroll mode (a skeleton row), and a sequential source and pages mode drop it. Make the sort total. */
  rows: TData[];
  /** Row count of the result. Omitted keeps the last known count; `null` declares it unknown. A value that is not a non-negative integer reads as `null` (dev-warned); a count above 10,000,000 clamps to it. */
  totalRowCount?: number | null;
  /** Rows exist after this block. Default: the block came back full. Random access and pages mode ignore it when a count is known; a sequential source ends on `false` also with a count. */
  hasMore?: boolean;
  /** Cursor sources: passed back as `cursor`. `null` ends the source. */
  nextCursor?: TCursor | null;
};

/** An answer after validation. */
export type ReadAnswer<TData, TCursor = never> = {
  /** The answer's rows in order; a later copy of a repeated id is `undefined`, so the other rows keep their positions. */
  rows: (TData | undefined)[];
  /** `undefined` keeps the last known count. */
  totalRowCount: number | null | undefined;
  hasMore: boolean;
  /** The `hasMore` the answer carried, if any. */
  hasMoreSent: boolean | undefined;
  nextCursor: TCursor | null | undefined;
};

/**
 * Validates an untrusted answer: `rows` must be an array and is cut to the requested size, `totalRowCount` must be a
 * non-negative safe integer (else unknown) and clamps to {@link MAX_ROW_COUNT}. Throws when the answer has no rows array.
 */
export function readAnswer<TData, TCursor = never>(
  answer: unknown,
  range: RowRange,
  warn: (kind: string, message: string) => void,
  idOf?: (row: TData, index: number) => string,
): ReadAnswer<TData, TCursor> {
  const raw = answer as Partial<ServerRowsAnswer<TData, TCursor>> | null | undefined;
  if (!Array.isArray(raw?.rows)) throw new TypeError("fetchRows of useDataGridServerRows must resolve with { rows: TData[] }");
  const limit = range.end - range.start;
  let rows: (TData | undefined)[] = raw.rows;
  if (rows.length > limit) {
    warn("long", `fetchRows returned ${rows.length} rows for a request of ${limit}; only the first ${limit} are used`);
    rows = rows.slice(0, limit);
  }
  const legacy = raw as { total?: unknown; hasNextPage?: unknown };
  if (("total" in legacy && !("totalRowCount" in raw)) || "hasNextPage" in legacy) {
    warn("legacy", "the answer of fetchRows uses `total` or `hasNextPage`; rename them to `totalRowCount` and `hasMore`");
  }
  let totalRowCount: number | null | undefined;
  if (raw.totalRowCount === undefined) totalRowCount = undefined;
  else if (raw.totalRowCount === null) totalRowCount = null;
  else if (typeof raw.totalRowCount === "number" && Number.isSafeInteger(raw.totalRowCount) && raw.totalRowCount >= 0) {
    totalRowCount = Math.min(raw.totalRowCount, MAX_ROW_COUNT);
    if (totalRowCount !== raw.totalRowCount) warn("count", `totalRowCount ${raw.totalRowCount} is above ${MAX_ROW_COUNT}; using ${MAX_ROW_COUNT}`);
  } else {
    totalRowCount = null;
    warn("count", "totalRowCount must be a non-negative integer or null; treating the count as unknown");
  }
  const full = rows.length === limit;
  if (idOf) rows = firstCopies(rows as TData[], idOf, range.start, warn);
  return {
    rows,
    totalRowCount,
    hasMore: typeof raw.hasMore === "boolean" ? raw.hasMore : full,
    hasMoreSent: typeof raw.hasMore === "boolean" ? raw.hasMore : undefined,
    nextCursor: raw.nextCursor,
  };
}

/** Keeps the first row of each id and blanks the later copies, so one answer never puts the same id twice into the grid. */
function firstCopies<TData>(rows: TData[], idOf: (row: TData, index: number) => string, start: number, warn: (kind: string, message: string) => void): (TData | undefined)[] {
  const seen = new Set<string>();
  let repeated = false;
  const kept = rows.map((row, index) => {
    const id = idOf(row, start + index);
    if (seen.has(id)) {
      repeated = true;
      return undefined;
    }
    seen.add(id);
    return row;
  });
  if (repeated) warn("duplicate", "fetchRows returned a duplicate row id; only the first row of each id is used, so make the sort total (add the row id as a last sort key)");
  return kept;
}

/** Options after the hook filled in the default `getRowId`. */
export type WithRowId<TOptions, TData> = TOptions & { getRowId: (row: TData, index: number) => string };

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { DataGridPlugin, FilterNode, ServerSpec, SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { MIN_RESHAPE_DELAY, MIN_REVALIDATE_INTERVAL, readReshapeDelay, readRevalidateInterval } from "./fetch-hygiene";

/** The request state every mode of `useDataGridServerRows` returns. */
export type DataSourceState = {
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec, or `null`. */
  error: unknown;
  /** Repeats the failed requests. Does nothing without an error. */
  retry: () => void;
  /** Fetches what is in view again and keeps it on screen until the answer lands. The hook calls it after saves settle by `refreshAfterSave`. */
  refresh: () => void;
  /** Asks the server to place the rows again after a push: one `refresh()` on the next frame, or after `reshapeDelayMs`. Calls in one frame join. */
  reshape: () => void;
};

/** Runs `callback` on the next animation frame, or after 16 ms where there is none. Returns the cancel. */
export function scheduleFrame(callback: () => void): () => void {
  if (typeof requestAnimationFrame === "function") {
    const id = requestAnimationFrame(callback);
    return () => cancelAnimationFrame(id);
  }
  const id = setTimeout(callback, 16);
  return () => clearTimeout(id);
}

const EMPTY_SPEC: ServerSpec = { sorts: [], filters: [], searchText: "" };

/** Controlled or uncontrolled state with a stable setter that always calls the latest `onChange`. */
export function useControlled<T>(controlled: T | undefined, initial: () => T, onChange: ((next: T) => void) | undefined) {
  const [inner, setInner] = useState(initial);
  const latest = useRef({ controlled, onChange });
  useLayoutEffect(() => {
    latest.current = { controlled, onChange };
  });
  const set = useCallback((next: T) => {
    if (latest.current.controlled === undefined) setInner(next);
    latest.current.onChange?.(next);
  }, []);
  return [controlled ?? inner, set] as const;
}

/** Runs a consumer callback so that a throw cannot break the caller's bookkeeping. */
export function isolate(label: string, call: () => void) {
  try {
    call();
  } catch (error) {
    console.error(`[data-grid-server] ${label} threw`, error);
  }
}

/** The refresh guard first, then the consumer's plugins; the array keeps its identity while `own` does. */
export function useMountedPlugins(guard: readonly DataGridPlugin<unknown>[], own?: readonly DataGridPlugin<unknown>[]) {
  return useMemo(() => (own && own.length > 0 ? [...guard, ...own] : guard), [guard, own]);
}

export type ServerSpecOptions = {
  spec?: ServerSpec;
  defaultSpec?: Partial<ServerSpec>;
  onSpecChange?: (spec: ServerSpec) => void;
};

/** The sort, filter, and search of a server source, with stable change handlers for the grid's controlled state. */
export function useServerSpec(source: ServerSpecOptions, afterChange: () => void) {
  const [spec, setSpec] = useControlled<ServerSpec>(
    source.spec,
    () => ({
      sorts: [...(source.defaultSpec?.sorts ?? EMPTY_SPEC.sorts)],
      filters: [...(source.defaultSpec?.filters ?? EMPTY_SPEC.filters)],
      searchText: source.defaultSpec?.searchText ?? EMPTY_SPEC.searchText,
    }),
    source.onSpecChange,
  );
  const live = useRef({ spec, afterChange });
  useLayoutEffect(() => {
    live.current = { spec, afterChange };
  });
  const changeSpec = useCallback(
    (next: Partial<ServerSpec>) => {
      const merged = { ...live.current.spec, ...next };
      // Two changes in one effect (a URL restore) merge instead of overwriting each other.
      live.current.spec = merged;
      setSpec(merged);
      live.current.afterChange();
    },
    [setSpec],
  );
  const onSortChange = useCallback((sorts: SortSpec[]) => changeSpec({ sorts }), [changeSpec]);
  const onFilterChange = useCallback((filters: FilterNode[]) => changeSpec({ filters }), [changeSpec]);
  const onSearchTextChange = useCallback((searchText: string) => changeSpec({ searchText }), [changeSpec]);
  return { spec, onSortChange, onFilterChange, onSearchTextChange };
}

type RevalidationInput = {
  /** The `revalidateIntervalMs` option as the consumer passed it. */
  interval: unknown;
  /** Runs the refresh when a tick is due. */
  onTick: () => void;
  /** A request is in flight: a due tick waits until this turns false and then runs once. */
  busy: boolean;
  /** `false` skips the tick and waits for the next one. */
  canTick?: () => boolean;
  /** A change restarts the clock. */
  resetKey: string;
};

/**
 * Runs `onTick` every `interval` ms while the page is visible. The clock chains `setTimeout`, so ticks never stack, and
 * `restart` (called by every refresh) pushes the next tick a full interval away. Returns `restart`.
 */
export function useRevalidation({ interval: raw, onTick, busy, canTick, resetKey }: RevalidationInput) {
  const { interval, invalid, raised } = readRevalidateInterval(raw);
  const live = useRef({ interval, onTick, busy, canTick });
  useLayoutEffect(() => {
    live.current = { interval, onTick, busy, canTick };
  });
  const clock = useRef<{ timer: ReturnType<typeof setTimeout> | null; deadline: number; waiting: boolean; warned: boolean; warnedRaised: boolean }>({ timer: null, deadline: 0, waiting: false, warned: false, warnedRaised: false });

  const fireRef = useRef<() => void>(() => {});
  const arm = useCallback(() => {
    const state = clock.current;
    if (state.timer !== null) clearTimeout(state.timer);
    state.timer = null;
    const { interval: ms } = live.current;
    if (ms === null || typeof document === "undefined" || document.visibilityState === "hidden") return;
    state.timer = setTimeout(() => {
      state.timer = null;
      fireRef.current();
    }, Math.max(0, state.deadline - Date.now()));
  }, []);

  const restart = useCallback(() => {
    clock.current.deadline = Date.now() + (live.current.interval ?? 0);
    clock.current.waiting = false;
    arm();
  }, [arm]);

  const fire = useCallback(() => {
    if (live.current.busy) {
      clock.current.waiting = true;
      return;
    }
    if (!live.current.canTick || live.current.canTick()) live.current.onTick();
    restart();
  }, [restart]);
  useLayoutEffect(() => {
    fireRef.current = fire;
  }, [fire]);

  useEffect(() => {
    if (invalid && isDev() && !clock.current.warned) {
      clock.current.warned = true;
      console.warn("[data-grid-server] revalidateIntervalMs must be a number of milliseconds above 0, so revalidation is off");
    }
  }, [invalid]);

  useEffect(() => {
    if (raised && isDev() && !clock.current.warnedRaised) {
      clock.current.warnedRaised = true;
      console.warn(`[data-grid-server] revalidateIntervalMs below ${MIN_REVALIDATE_INTERVAL} ms is raised to ${MIN_REVALIDATE_INTERVAL} ms`);
    }
  }, [raised]);

  useEffect(() => {
    if (interval === null || typeof document === "undefined") return;
    restart();
    const onVisibility = () => {
      if (document.visibilityState === "hidden") {
        if (clock.current.timer !== null) clearTimeout(clock.current.timer);
        clock.current.timer = null;
      } else if (Date.now() >= clock.current.deadline) fire();
      else arm();
    };
